<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigLoginVO;

trait SmtpOutboundConfigLoginAttributeHolder
{
    protected SmtpOutboundConfigLoginVO|string|null $login = null;
    protected bool $loginAssigned = false;

    public function getLoginOrCurrent(SmtpOutboundConfigLoginVO $login): SmtpOutboundConfigLoginVO
    {
        if ($this->loginAssigned) {
            \assert(null !== $this->login);
            return SmtpOutboundConfigLoginVO::from($this->login);
        } else {
            return $login;
        }
    }
    public function loginTryBuildInitial(ConstraintFailList $error): ?SmtpOutboundConfigLoginVO
    {
        return  SmtpOutboundConfigLoginVO::tryFrom($this->loginAssigned ? $this->login : null, $error);
    }
    public function login(SmtpOutboundConfigLoginVO|string $login): static
    {
        $this->login = $login;
        $this->loginAssigned = true;
        return $this;
    }
    public function getLogin(): ?string
    {
        return $this->login instanceof SmtpOutboundConfigLoginVO ? $this->login->value() : $this->login;
    }
    public function isLoginAssigned(): bool
    {
        return $this->loginAssigned;
    }
    public function writeLoginTo(mixed $att): void
    {
        if ($this->loginAssigned) {
            \assert(null !== $this->login);
            $att->login($this->login);
        }
    }
    public function readLoginFrom(mixed $att): void
    {
        if ($att->isLoginAssigned()) {
            $login = $att->getLogin();
            \assert(null !== $login);
            $this->login($login);
        }
    }
    public function unsetLogin(): static
    {
        $this->loginAssigned = false;
        return $this;
    }
    protected function withDefaultLogin(): void
    {
    }
    protected function withAssertedLoginRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->loginAssigned = $this->loginAssigned) {
            $value->login = SmtpOutboundConfigLoginVO::tryFrom($this->login, $errorsList);
        }
    }
}
